<?php include "../includes/auth.php"; include "../config/connection.php"; include "../includes/header.php"; $row=null;$error="";if($_SERVER["REQUEST_METHOD"]=="POST"){$id=trim($_POST['customer_id']??'');if(!ctype_digit($id)||(int)$id<1||strlen($id)>8)$error="Please enter a valid customer ID.";else{$id=(int)$id;$r=mysqli_query($conn,"SELECT id,name,email,city,salary FROM customers WHERE id=$id");if($r&&mysqli_num_rows($r))$row=mysqli_fetch_assoc($r);else $error="Customer not found.";}} ?>
<h2>Find Customer By ID</h2><form method="POST" class="row g-2 my-3"><div class="col-sm-5"><input type="number" name="customer_id" min="1" max="99999999" class="form-control" placeholder="Enter customer ID" required></div><div class="col-sm-3"><button class="btn btn-primary">Search</button></div></form><?php if($error): ?><div class="alert alert-warning"><?php echo htmlspecialchars($error); ?></div><?php endif; ?><?php if($row): ?><div class="card p-3"><h4><?php echo htmlspecialchars($row['name']); ?></h4><p><b>ID:</b> <?php echo $row['id']; ?></p><p><b>Email:</b> <?php echo htmlspecialchars($row['email']); ?></p><p><b>City:</b> <?php echo htmlspecialchars($row['city']); ?></p><p class="mb-0"><b>Salary:</b> <?php echo number_format($row['salary'],2); ?></p></div><?php endif; ?><a href="../index.php" class="btn btn-secondary mt-3">Back Home</a><?php include "../includes/footer.php"; ?>